c5-4.solution:
#include <stdio.h>

int main(void) {
    int score;
    if (scanf("%d", &score) != 1) { puts("Invalid"); }
    else if (score < 0 || score > 100) { puts("Invalid"); }
    else { puts("Valid"); }
    return 0;
}

