    return 0;
}

c5-5.solution:
#include <stdio.h>

int main(void) {
    double a, b;
    if (scanf("%lf %lf", &a, &b) != 2 || b == 0) { puts("Invalid"); }
    else { printf("%.2f\n", a / b); }
    return 0;
}
